#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO_ROOT=$(cd "$SCRIPT_DIR/.." && pwd)
ENV_FILE="${STAGING_ENV_FILE:-$REPO_ROOT/infra/.staging/.dev.vars}"
WRANGLER=(npx wrangler)

fail_setup() {
  warn "$1"
  exit 1
}

valid_https_origin() {
  node -e '
    try {
      const raw = process.argv[1];
      const url = new URL(raw);
      const local = ["localhost", "127.0.0.1", "0.0.0.0", "::1", "[::1]"].includes(url.hostname) || url.hostname.endsWith(".localhost");
      const example = url.hostname === "example.com" || url.hostname.endsWith(".example.com");
      if (url.protocol !== "https:" || local || example ||
          url.pathname !== "/" || url.search || url.hash || url.username || url.password) process.exit(1);
    } catch { process.exit(1); }
  ' "$1"
}

ask_public_url() {
  local key="$1" prompt="$2"
  ask "$key" "$prompt"
  while ! valid_https_origin "${!key}"; do
    warn "Use an HTTPS origin only, with no path, credentials, or example.com hostname."
    ask "$key" "$prompt"
  done
  printf -v "$key" '%s' "${!key%/}"
}

ask_https_url() {
  local key="$1" prompt="$2"
  ask "$key" "$prompt"
  while ! node -e '
    try {
      const url = new URL(process.argv[1]);
      const local = ["localhost", "127.0.0.1", "0.0.0.0", "::1", "[::1]"].includes(url.hostname) || url.hostname.endsWith(".localhost");
      const example = url.hostname === "example.com" || url.hostname.endsWith(".example.com");
      if (url.protocol !== "https:" || local || example || url.username || url.password) process.exit(1);
    } catch { process.exit(1); }
  ' "${!key}"; do
    warn "Use a real non-local HTTPS URL without credentials or an example.com hostname."
    ask "$key" "$prompt"
  done
}

capture_secret() {
  local key="$1" prompt="$2"
  ask_secret "$key" "$prompt"
  while [[ -z "${!key}" ]]; do
    warn "A non-empty value is required."
    ask_secret "$key" "$prompt"
  done
  write_env "$key" "${!key}"
}

put_secret() {
  local worker="$1" key="$2" value="$3"
  if printf '%s' "$value" | "${WRANGLER[@]}" secret put "$key" \
    --config "$REPO_ROOT/infra/wrangler.$worker.toml" --env staging >/dev/null; then
    say "✓ set $worker/$key"
  else
    fail_setup "Could not set $worker/$key. Re-run the wizard; no secret value was printed."
  fi
}

ensure_queue() {
  local name="$1"
  if "${WRANGLER[@]}" queues info "$name" >/dev/null 2>&1; then
    say "✓ queue exists: $name"
  else
    "${WRANGLER[@]}" queues create "$name" >/dev/null || fail_setup "Could not create queue $name."
    say "✓ created queue: $name"
  fi
}

hyperdrive_id_from_list() {
  "${WRANGLER[@]}" hyperdrive list 2>/dev/null | node -e '
    let input = "";
    process.stdin.on("data", (chunk) => input += chunk);
    process.stdin.on("end", () => {
      const clean = input.replace(/\x1b\[[0-9;]*m/g, "");
      for (const line of clean.split("\n")) {
        if (line.includes(process.argv[1])) {
          const match = line.match(/[0-9a-f]{32}/i);
          if (match) { process.stdout.write(match[0]); return; }
        }
      }
      process.exit(1);
    });
  ' "$1"
}

kv_id_from_list() {
  "${WRANGLER[@]}" kv namespace list 2>/dev/null | node -e '
    let input = "";
    process.stdin.on("data", (chunk) => input += chunk);
    process.stdin.on("end", () => {
      try {
        const list = JSON.parse(input);
        const found = list.find((item) => item.title === process.argv[1]);
        if (found) { process.stdout.write(found.id); return; }
      } catch {}
      process.exit(1);
    });
  ' "$1"
}

run_wizard() {

TOTAL_STAGES=16

cd "$REPO_ROOT" || fail_setup "Run from the market-runs repository."
mkdir -p "$(dirname "$ENV_FILE")"
chmod 700 "$(dirname "$ENV_FILE")" 2>/dev/null || true
[[ ! -f "$ENV_FILE" ]] || chmod 600 "$ENV_FILE"
if ! _existing RECONCILE_PROVIDER_SINCE >/dev/null; then
  write_env RECONCILE_PROVIDER_SINCE "$(date -u +"%Y-%m-%dT%H:%M:%SZ")"
fi

banner "Market Runs staging provisioning"

stage "Preflight and scope"
say "Paid staging uses Flutterwave TEST keys, Smile ID sandbox, and hybrid identity; stub is infrastructure-only."
say "OSRM remains excluded. The biometrics service is an external prerequisite, not deployed by this wizard."
say "State and secrets go only to gitignored $ENV_FILE or wrangler secret put."
for cli in node npx curl; do
  command -v "$cli" >/dev/null 2>&1 || fail_setup "Install $cli before continuing."
done
for file in package.json infra/staging-toml.mjs infra/staging-check.sh infra/staging-db-check.mjs; do
  [[ -f "$REPO_ROOT/$file" ]] || fail_setup "Missing $file; restore the complete staging wizard files."
done
if ! "${WRANGLER[@]}" whoami >/dev/null 2>&1; then
  say "Wrangler is not authenticated. Login opens Cloudflare in your browser."
  if confirm "Run wrangler login now?"; then
    "${WRANGLER[@]}" login || fail_setup "Wrangler login failed."
  else
    fail_setup "Run npx wrangler login, then re-run this wizard."
  fi
fi
"${WRANGLER[@]}" whoami >/dev/null 2>&1 || fail_setup "Wrangler authentication is still unavailable."
say "✓ Wrangler authentication is available."

stage "Launch market and public HTTPS routes"
say "Use stable staging origins already mapped to the five Workers; enter origins without paths."
ask LAUNCH_MARKET "Launch market name (for example: Yaba):"
while [[ ! "$LAUNCH_MARKET" =~ ^[A-Za-z0-9][A-Za-z0-9\ ._-]{0,63}$ ]]; do
  warn "Use 1-64 letters, numbers, spaces, dots, underscores, or hyphens."
  ask LAUNCH_MARKET "Launch market name:"
done
write_env LAUNCH_MARKET "$LAUNCH_MARKET"
if [[ "$LAUNCH_MARKET" != Balogun && "$LAUNCH_MARKET" != "Computer Village" ]]; then
  say "A custom market needs its real geofence; the CLI has no fallback geography."
  ask LAUNCH_MARKET_LATITUDE "Market center latitude:"
  ask LAUNCH_MARKET_LONGITUDE "Market center longitude:"
  ask LAUNCH_MARKET_RADIUS_METERS "Geofence radius in meters (positive integer):"
  write_env LAUNCH_MARKET_LATITUDE "$LAUNCH_MARKET_LATITUDE"
  write_env LAUNCH_MARKET_LONGITUDE "$LAUNCH_MARKET_LONGITUDE"
  write_env LAUNCH_MARKET_RADIUS_METERS "$LAUNCH_MARKET_RADIUS_METERS"
fi
ask_public_url EDGE_PUBLIC_URL "Edge public HTTPS origin (also OPS_BASE_URL):"
ask_public_url ARCHIVE_PUBLIC_URL "Archive public HTTPS origin:"
ask_public_url IDENTITY_PUBLIC_URL "Identity public HTTPS origin:"
ask_public_url PAYMENTS_PUBLIC_URL "Payments public HTTPS origin:"
ask_public_url NOTIFICATIONS_PUBLIC_URL "Notifications public HTTPS origin:"
if ! node -e '
  const origins = process.argv.slice(1).map((value) => new URL(value).origin);
  process.exit(new Set(origins).size === origins.length ? 0 : 1);
' "$EDGE_PUBLIC_URL" "$ARCHIVE_PUBLIC_URL" "$IDENTITY_PUBLIC_URL" "$PAYMENTS_PUBLIC_URL" "$NOTIFICATIONS_PUBLIC_URL"; then
  fail_setup "The five public Worker origins must be distinct."
fi
ask RESEND_FROM_EMAIL "Verified Resend sender (for example: Market Runs <staging@your-domain>):"
[[ -n "$RESEND_FROM_EMAIL" ]] || fail_setup "RESEND_FROM_EMAIL is required."
for key in EDGE_PUBLIC_URL ARCHIVE_PUBLIC_URL IDENTITY_PUBLIC_URL PAYMENTS_PUBLIC_URL NOTIFICATIONS_PUBLIC_URL RESEND_FROM_EMAIL; do
  write_env "$key" "${!key}"
done
write_env OPS_BASE_URL "$EDGE_PUBLIC_URL"

stage "Payment posture"
say "Choose flutterwave for a real paid/hybrid rehearsal with TEST and sandbox credentials, or stub for infrastructure only."
ask PAYMENT_DISPATCHER "Dispatcher (flutterwave/stub):"
while [[ "$PAYMENT_DISPATCHER" != flutterwave && "$PAYMENT_DISPATCHER" != stub ]]; do
  ask PAYMENT_DISPATCHER "Enter exactly flutterwave or stub:"
done
write_env PAYMENT_DISPATCHER "$PAYMENT_DISPATCHER"
if [[ "$PAYMENT_DISPATCHER" == flutterwave ]]; then
  write_env PAYMENTS_REQUIRED true
  write_env FACE_VERIFIER hybrid
  ask FLUTTERWAVE_PUBLIC_KEY "Flutterwave TEST public key for the mobile app:"
  [[ "$FLUTTERWAVE_PUBLIC_KEY" == FLWPUBK_TEST-* ]] || fail_setup "Staging requires a FLWPUBK_TEST- public key."
  write_env FLUTTERWAVE_PUBLIC_KEY "$FLUTTERWAVE_PUBLIC_KEY"
  ask GOOGLE_MAPS_API_KEY "Google Maps API key for staging EAS builds:"
  [[ -n "$GOOGLE_MAPS_API_KEY" ]] || fail_setup "GOOGLE_MAPS_API_KEY is required for staging mobile builds."
  write_env GOOGLE_MAPS_API_KEY "$GOOGLE_MAPS_API_KEY"
else
  write_env PAYMENTS_REQUIRED false
  write_env FACE_VERIFIER stub
  warn "Stub selects payment and identity stubs. It cannot approve a real paid/hybrid rehearsal."
fi

stage "Hybrid identity and private biometrics"
if [[ "$FACE_VERIFIER" == hybrid ]]; then
  write_env SMILEID_ENV sandbox
  SMILEID_CALLBACK_URL="$EDGE_PUBLIC_URL/callbacks/smileid"
  write_env SMILEID_CALLBACK_URL "$SMILEID_CALLBACK_URL"
  open_url "https://portal.usesmileid.com/"
  step "Select the Smile ID sandbox environment and locate callback/webhook settings (portal labels can vary)."
  step "Set the callback to $SMILEID_CALLBACK_URL; this edge route proxies to identity for signature verification."
  step "Publish the approved privacy notice at a stable public HTTPS URL before enrollment."
  ask_https_url SMILEID_PRIVACY_NOTICE_URL "Published Smile ID privacy notice HTTPS URL:"
  write_env SMILEID_PRIVACY_NOTICE_URL "$SMILEID_PRIVACY_NOTICE_URL"
  curl --fail --silent --show-error --max-time 15 --output /dev/null "$SMILEID_PRIVACY_NOTICE_URL" || fail_setup "The privacy notice URL must be publicly reachable over HTTPS."
  capture_secret SMILEID_PARTNER_ID "Smile ID sandbox partner id (hidden):"
  capture_secret SMILEID_API_KEY "Smile ID sandbox API key (hidden):"
  say "The biometrics service must already be deployed privately with ArcFace and MiniFASNet ONNX artifacts."
  say "This wizard does not deploy biometrics or models and does not expose a mobile biometrics route."
  ask_public_url BIOMETRICS_SERVICE_URL "Private biometrics non-local HTTPS origin:"
  write_env BIOMETRICS_SERVICE_URL "$BIOMETRICS_SERVICE_URL"
  capture_secret BIOMETRICS_SERVICE_TOKEN "Identity BIOMETRICS_SERVICE_TOKEN (32+ characters, hidden):"
  [[ ${#BIOMETRICS_SERVICE_TOKEN} -ge 32 ]] || fail_setup "BIOMETRICS_SERVICE_TOKEN must contain at least 32 characters."
  say "Set biometrics BIOMETRICS_INTERNAL_TOKEN to exactly the same value as identity BIOMETRICS_SERVICE_TOKEN."
  BIOMETRICS_HEALTH=$(curl --fail --silent --show-error --max-time 15 "$BIOMETRICS_SERVICE_URL/healthz") || fail_setup "Biometrics /healthz is not reachable at the captured HTTPS origin."
  if ! printf '%s' "$BIOMETRICS_HEALTH" | node -e '
    let input = ""; process.stdin.on("data", (chunk) => input += chunk);
    process.stdin.on("end", () => {
      try {
        const health = JSON.parse(input);
        process.exit(health.service === "market-runs-biometrics" && typeof health.modelVersion === "string" && health.modelVersion ? 0 : 1);
      } catch { process.exit(1); }
    });
  '; then
    fail_setup "Biometrics /healthz did not report the expected service and model version."
  fi
  unset BIOMETRICS_HEALTH
  if ! confirm "Confirm real ArcFace/MiniFASNet models, matching biometrics token, and reachable HTTPS are deployed?"; then
    fail_setup "Hybrid staging requires the externally deployed, model-ready biometrics service."
  fi
  pause "Confirm the Smile ID sandbox callback and published privacy notice are configured."
else
  say "Infrastructure-only stub selected: no Smile ID, biometrics, or capture-bucket rehearsal is approved."
fi

stage "Neon and Hyperdrive"
open_url "https://console.neon.tech/"
step "Open the staging Neon project's connection details and copy its pooled Postgres URI."
step "Use a staging database, not production. UI labels vary by Neon plan."
ask_secret DATABASE_URL "Paste the Neon connection string (hidden):"
while [[ "$DATABASE_URL" != postgres://* && "$DATABASE_URL" != postgresql://* ]]; do
  warn "The connection string must be a postgres:// or postgresql:// URI."
  ask_secret DATABASE_URL "Paste the Neon connection string (hidden):"
done
write_env DATABASE_URL "$DATABASE_URL"
HYPERDRIVE_NAME=market-runs-staging
HYPERDRIVE_ID=$(_existing HYPERDRIVE_ID || true)
if [[ -z "$HYPERDRIVE_ID" ]]; then HYPERDRIVE_ID=$(hyperdrive_id_from_list "$HYPERDRIVE_NAME" || true); fi
if [[ -n "$HYPERDRIVE_ID" ]]; then
  say "✓ reusing Hyperdrive $HYPERDRIVE_ID"
  if confirm "Point this Hyperdrive at the captured Neon URI (recommended after a database change)?"; then
    UPDATE_OUTPUT=$("${WRANGLER[@]}" hyperdrive update "$HYPERDRIVE_ID" \
      --connection-string "$DATABASE_URL" 2>&1) || fail_setup "Hyperdrive update failed; check Neon and Wrangler access."
    unset UPDATE_OUTPUT
    say "✓ Hyperdrive origin updated without printing the connection string"
  else
    say "Kept the existing Hyperdrive origin; ensure it matches the migration database."
  fi
elif confirm "Create Hyperdrive $HYPERDRIVE_NAME with the captured Neon URI?"; then
  CREATE_OUTPUT=$("${WRANGLER[@]}" hyperdrive create "$HYPERDRIVE_NAME" \
    --connection-string "$DATABASE_URL" 2>&1) || fail_setup "Hyperdrive creation failed; check Neon and Wrangler access."
  HYPERDRIVE_ID=$(printf '%s' "$CREATE_OUTPUT" | node -e '
    let input = ""; process.stdin.on("data", (c) => input += c);
    process.stdin.on("end", () => {
      const match = input.match(/[0-9a-f]{32}/i);
      if (match) process.stdout.write(match[0]); else process.exit(1);
    });
  ') || fail_setup "Hyperdrive was created but its ID could not be parsed; re-run to reuse it."
  say "✓ created Hyperdrive $HYPERDRIVE_ID"
else
  fail_setup "Hyperdrive is required for every deployed Worker."
fi
write_env HYPERDRIVE_ID "$HYPERDRIVE_ID"
unset CREATE_OUTPUT

stage "Queues, DLQs, and private R2"
say "Existing resources are reused; missing resources are created with the configured staging names."
if confirm "Reconcile the six queues/DLQs and required private R2 buckets now?"; then
  for queue in archive-snapshots-staging archive-snapshots-dlq-staging \
    payment-dispatch-staging payment-dispatch-dlq-staging \
    notification-events-staging notification-events-dlq-staging; do
    ensure_queue "$queue"
  done
  buckets=(market-runs-archive-staging)
  if [[ "$FACE_VERIFIER" == hybrid ]]; then buckets+=(market-runs-identity-captures-staging); fi
  for bucket in "${buckets[@]}"; do
    if "${WRANGLER[@]}" r2 bucket info "$bucket" >/dev/null 2>&1; then
      say "✓ R2 bucket exists: $bucket"
    else
      "${WRANGLER[@]}" r2 bucket create "$bucket" >/dev/null || fail_setup "Could not create R2 bucket $bucket."
      say "✓ created private R2 bucket: $bucket"
    fi
  done
  if [[ "$FACE_VERIFIER" == hybrid ]]; then
    say "IDENTITY_CAPTURES stays private: never attach a public bucket domain or public read route."
  fi
else
  fail_setup "Queues, DLQs, and required R2 buckets are required."
fi

stage "KV MARKET_CONFIG"
KV_TITLE=market-runs-market-config-staging
MARKET_CONFIG_KV_ID=$(_existing MARKET_CONFIG_KV_ID || true)
if [[ -z "$MARKET_CONFIG_KV_ID" ]]; then MARKET_CONFIG_KV_ID=$(kv_id_from_list "$KV_TITLE" || true); fi
if [[ -n "$MARKET_CONFIG_KV_ID" ]]; then
  say "✓ reusing KV namespace $MARKET_CONFIG_KV_ID"
elif confirm "Create KV namespace $KV_TITLE for binding MARKET_CONFIG?"; then
  KV_OUTPUT=$("${WRANGLER[@]}" kv namespace create "$KV_TITLE" 2>&1) || fail_setup "KV namespace creation failed."
  MARKET_CONFIG_KV_ID=$(printf '%s' "$KV_OUTPUT" | node -e '
    let input = ""; process.stdin.on("data", (c) => input += c);
    process.stdin.on("end", () => {
      const match = input.match(/[0-9a-f]{32}/i);
      if (match) process.stdout.write(match[0]); else process.exit(1);
    });
  ') || fail_setup "KV was created but its ID could not be parsed; re-run to reuse it."
  say "✓ created KV namespace $MARKET_CONFIG_KV_ID"
else
  fail_setup "MARKET_CONFIG KV is required."
fi
write_env MARKET_CONFIG_KV_ID "$MARKET_CONFIG_KV_ID"
unset KV_OUTPUT

stage "Public staging TOML updates"
say "Only public [env.staging] values and resource IDs will change in five wrangler.*.toml files."
say "The update sets OPS_BASE_URL, disables staging OSRM, and applies the selected $FACE_VERIFIER identity mode."
if ! confirm "Apply these tracked public TOML updates now?"; then
  SKIPPED+=("Public staging TOML updates; placeholders intentionally preserved")
  warn "Skipped: no tracked TOML was changed. Re-run when ready to continue."
  finish
  return 0
fi
EDGE_PUBLIC_URL="$EDGE_PUBLIC_URL" ARCHIVE_PUBLIC_URL="$ARCHIVE_PUBLIC_URL" \
IDENTITY_PUBLIC_URL="$IDENTITY_PUBLIC_URL" PAYMENTS_PUBLIC_URL="$PAYMENTS_PUBLIC_URL" \
NOTIFICATIONS_PUBLIC_URL="$NOTIFICATIONS_PUBLIC_URL" RESEND_FROM_EMAIL="$RESEND_FROM_EMAIL" \
HYPERDRIVE_ID="$HYPERDRIVE_ID" MARKET_CONFIG_KV_ID="$MARKET_CONFIG_KV_ID" \
PAYMENT_DISPATCHER="$PAYMENT_DISPATCHER" FACE_VERIFIER="$FACE_VERIFIER" \
SMILEID_ENV="${SMILEID_ENV:-}" SMILEID_CALLBACK_URL="${SMILEID_CALLBACK_URL:-}" \
SMILEID_PRIVACY_NOTICE_URL="${SMILEID_PRIVACY_NOTICE_URL:-}" BIOMETRICS_SERVICE_URL="${BIOMETRICS_SERVICE_URL:-}" \
node infra/staging-toml.mjs apply || fail_setup "Public TOML update failed."

stage "Edge and identity auth secrets"
say "Generate independent random values with at least 32 characters; input stays hidden."
say "IDENTITY_SESSION_SECRET and IDENTITY_INTERNAL_TOKEN are shared verbatim by edge and identity."
capture_secret OPS_AUTH_SECRET "OPS_AUTH_SECRET (32+ characters):"
[[ ${#OPS_AUTH_SECRET} -ge 32 ]] || fail_setup "OPS_AUTH_SECRET must contain at least 32 characters."
capture_secret ID_DOCUMENT_HMAC_SECRET "ID_DOCUMENT_HMAC_SECRET:"
capture_secret IDENTITY_SESSION_SECRET "IDENTITY_SESSION_SECRET:"
capture_secret IDENTITY_INTERNAL_TOKEN "IDENTITY_INTERNAL_TOKEN:"
capture_secret IDENTITY_ENCRYPTION_KEY "IDENTITY_ENCRYPTION_KEY (base64-encoded 32 bytes):"
printf '%s' "$IDENTITY_ENCRYPTION_KEY" | node -e '
  let value = ""; process.stdin.on("data", (c) => value += c);
  process.stdin.on("end", () => {
    try { if (Buffer.from(value, "base64").length !== 32) process.exit(1); } catch { process.exit(1); }
  });
' || fail_setup "IDENTITY_ENCRYPTION_KEY must decode to exactly 32 bytes."
put_secret edge OPS_AUTH_SECRET "$OPS_AUTH_SECRET"
put_secret edge ID_DOCUMENT_HMAC_SECRET "$ID_DOCUMENT_HMAC_SECRET"
put_secret edge IDENTITY_SESSION_SECRET "$IDENTITY_SESSION_SECRET"
put_secret edge IDENTITY_INTERNAL_TOKEN "$IDENTITY_INTERNAL_TOKEN"
put_secret identity IDENTITY_SESSION_SECRET "$IDENTITY_SESSION_SECRET"
put_secret identity IDENTITY_INTERNAL_TOKEN "$IDENTITY_INTERNAL_TOKEN"
put_secret identity IDENTITY_ENCRYPTION_KEY "$IDENTITY_ENCRYPTION_KEY"
if [[ "$FACE_VERIFIER" == hybrid ]]; then
  put_secret identity SMILEID_PARTNER_ID "$SMILEID_PARTNER_ID"
  put_secret identity SMILEID_API_KEY "$SMILEID_API_KEY"
  put_secret identity BIOMETRICS_SERVICE_TOKEN "$BIOMETRICS_SERVICE_TOKEN"
fi

stage "Archive, notifications, and payments service auth"
say "Each token is shared only between edge and its owning Worker."
capture_secret ARCHIVE_INTERNAL_TOKEN "ARCHIVE_INTERNAL_TOKEN:"
capture_secret NOTIFICATION_INTERNAL_TOKEN "NOTIFICATION_INTERNAL_TOKEN:"
capture_secret PAYMENTS_INTERNAL_TOKEN "PAYMENTS_INTERNAL_TOKEN:"
put_secret edge ARCHIVE_INTERNAL_TOKEN "$ARCHIVE_INTERNAL_TOKEN"
put_secret archive ARCHIVE_INTERNAL_TOKEN "$ARCHIVE_INTERNAL_TOKEN"
put_secret edge NOTIFICATION_INTERNAL_TOKEN "$NOTIFICATION_INTERNAL_TOKEN"
put_secret notifications NOTIFICATION_INTERNAL_TOKEN "$NOTIFICATION_INTERNAL_TOKEN"
put_secret edge PAYMENTS_INTERNAL_TOKEN "$PAYMENTS_INTERNAL_TOKEN"
put_secret payments PAYMENTS_INTERNAL_TOKEN "$PAYMENTS_INTERNAL_TOKEN"

stage "Flutterwave and Resend secrets"
open_url "https://dashboard.flutterwave.com/"
step "In Settings → API keys, copy the TEST secret key. Never use a live key in staging."
capture_secret FLUTTERWAVE_SECRET_KEY "FLUTTERWAVE_SECRET_KEY (FLWSECK_TEST-…, hidden):"
if [[ "$PAYMENT_DISPATCHER" == flutterwave && "$FLUTTERWAVE_SECRET_KEY" != FLWSECK_TEST-* ]]; then
  fail_setup "Paid staging requires a FLWSECK_TEST- key."
fi
step "In Settings → Webhooks, copy or create the secret hash used for transfer callbacks."
capture_secret FLUTTERWAVE_WEBHOOK_SECRET_HASH "FLUTTERWAVE_WEBHOOK_SECRET_HASH (hidden):"
open_url "https://resend.com/api-keys"
step "Create or copy a Resend API key for the verified staging sender."
capture_secret RESEND_API_KEY "RESEND_API_KEY (hidden):"
put_secret payments FLUTTERWAVE_SECRET_KEY "$FLUTTERWAVE_SECRET_KEY"
put_secret payments FLUTTERWAVE_WEBHOOK_SECRET_HASH "$FLUTTERWAVE_WEBHOOK_SECRET_HASH"
put_secret notifications RESEND_API_KEY "$RESEND_API_KEY"

stage "Migrations through 0018 and launch market"
say "Drizzle migrates Neon directly; Hyperdrive is runtime-only. Re-running is idempotent."
if confirm "Apply pending migrations through 0018 to the captured staging database?"; then
  (cd "$REPO_ROOT/infra/drizzle" && DATABASE_URL="$DATABASE_URL" npx drizzle-kit migrate) || fail_setup "Drizzle migration failed."
else
  fail_setup "Migration 0018 is a go/no-go requirement."
fi
MARKET_ARGS=("$LAUNCH_MARKET")
if [[ "$LAUNCH_MARKET" != Balogun && "$LAUNCH_MARKET" != "Computer Village" ]]; then
  MARKET_ARGS+=(--latitude "$LAUNCH_MARKET_LATITUDE" --longitude "$LAUNCH_MARKET_LONGITUDE" --radius-meters "$LAUNCH_MARKET_RADIUS_METERS")
fi
if confirm "Seed or repair launch market $LAUNCH_MARKET with the captured geofence?"; then
  DATABASE_URL="$DATABASE_URL" OPS_AUTH_SECRET="$OPS_AUTH_SECRET" OPS_BASE_URL="$EDGE_PUBLIC_URL" \
    npx pnpm@9.15.4 --filter @market-runs/edge ops:seed-markets -- "${MARKET_ARGS[@]}" || fail_setup "Launch-market seed failed."
else
  fail_setup "The launch market must be seeded before go/no-go."
fi

stage "First ops administrator"
say "This one-time CLI succeeds only when no operator exists. The password must have 12+ characters."
if confirm "Bootstrap the first ops admin now (skip on re-runs if one exists)?"; then
  ask OPS_ADMIN_EMAIL "Ops admin email:"
  write_env OPS_ADMIN_EMAIL "$OPS_ADMIN_EMAIL"
  ask_secret OPS_ADMIN_PASSWORD "Temporary ops admin password (hidden):"
  [[ ${#OPS_ADMIN_PASSWORD} -ge 12 ]] || fail_setup "The ops admin password must contain at least 12 characters."
  DATABASE_URL="$DATABASE_URL" OPS_AUTH_SECRET="$OPS_AUTH_SECRET" OPS_BASE_URL="$EDGE_PUBLIC_URL" \
    OPS_REQUIRE_PASSWORD_CHANGE=true npx pnpm@9.15.4 --filter @market-runs/edge ops:bootstrap-admin -- \
    --email "$OPS_ADMIN_EMAIL" --password "$OPS_ADMIN_PASSWORD" || fail_setup "Ops admin bootstrap failed; if an operator exists, re-run and skip this stage."
  OPS_ADMIN_PASSWORD=""
  say "✓ first admin created; a password change is required at first login."
else
  SKIPPED+=("Ops admin bootstrap (only acceptable when an admin already exists)")
fi

stage "Paid configuration and webhook"
if [[ "$PAYMENT_DISPATCHER" == flutterwave ]]; then
  open_url "https://dashboard.flutterwave.com/"
  step "Settings → Webhooks: set the transfer webhook to $EDGE_PUBLIC_URL/webhooks/transfers"
  step "Use the exact secret hash captured earlier. Do not enable FLUTTERWAVE_TEST_MODE in staging."
  step "Set EAS EXPO_PUBLIC_EDGE_URL=$EDGE_PUBLIC_URL for the staging build environment."
  step "Set EAS EXPO_PUBLIC_FLW_PUBLIC_KEY to the captured FLWPUBK_TEST- public key."
  step "Set EAS GOOGLE_MAPS_API_KEY to the captured, Android-restricted staging Maps key."
  step "The TOML paid gate is PAYMENTS_REQUIRED=true and payments uses the flutterwave dispatcher."
  pause "Confirm the Flutterwave webhook and all three staging EAS values are configured."
else
  warn "Stub selected: skip paid/hybrid rehearsal. Strict go/no-go will remain NO-GO by design."
fi

stage "Archive-first deployment (ADR-0029)"
say "Prerequisite: the external biometrics service is already healthy; this wizard does not deploy it."
say "Worker order: archive → identity → payments → notifications → edge. The archive producer lands before edge."
say "Routes must already map the captured public origins to these staging Workers."
if confirm "Deploy the five staging Workers in archive-first order now?"; then
  for worker in archive identity payments notifications edge; do
    say "Deploying $worker…"
    "${WRANGLER[@]}" deploy --config "$REPO_ROOT/infra/wrangler.$worker.toml" --env staging || fail_setup "$worker deployment failed; use the runbook rollback procedure."
  done
else
  SKIPPED+=("Five-worker archive-first deployment")
  warn "Deployment skipped. Use docs/runbooks/staging-deployment.md when ready."
fi

stage "Executable go/no-go and reconciliation"
say "The checker validates resources, secret names, migration 0018, market/admin, health, auth, and money tie-out."
say "It never prints secrets. Any FAIL, reconciliation WARN, or skipped paid vendor check is NO-GO."
if confirm "Run the strict staging go/no-go now?"; then
  if bash "$REPO_ROOT/infra/staging-check.sh"; then
    say "✓ GO: all strict staging checks passed."
  else
    SKIPPED+=("Strict go/no-go is NO-GO; resolve the listed failures before a paid test")
    warn "NO-GO: resolve every listed failure and rerun bash infra/staging-check.sh."
  fi
else
  SKIPPED+=("Strict go/no-go (bash infra/staging-check.sh)")
fi
say "Deployment, recovery, and rollback details: docs/runbooks/staging-deployment.md"
finish
}

run_wizard "$@"; exit
